// Arquivo completo para: src/api/axios.js

import axios from 'axios';

// Cria uma instância do Axios com a URL base da sua API
const instance = axios.create({
    baseURL: 'http://localhost:8000/api' 
} );

// ADICIONADO: Interceptador de Respostas
// Esta função será chamada para cada resposta que o Axios receber.
instance.interceptors.response.use(
    (response) => response,
    (error) => {
        const { config, response } = error;
        // Verifica se o erro é 401 E se a rota original NÃO é a de solicitar código de senha
        if (response && response.status === 401 && config.url !== '/users/me/request-password-change') {
            localStorage.removeItem('token');
            localStorage.removeItem('userData');
            window.location.href = '/login';
            alert("Sua sessão expirou. Por favor, faça login novamente.");
        }
        return Promise.reject(error);
    }
);
export default instance;
